SELECT channel, CASE WHEN discount >= 0.34 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, status, STDDEV_SAMP(shipping_fee) AS shipping_fee_stddev, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN channel = 'partner' THEN 1 END), 0), 2) AS amount_per_partner, APPROX_PERCENTILE(discount, 0.5) AS discount_p50, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN status = 'RETURNED' THEN 1 END), 0), 2) AS discount_per_returned, COUNT(*) AS row_count, PERCENT_RANK() OVER (PARTITION BY channel ORDER BY APPROX_PERCENTILE(discount, 0.5) DESC) AS discount_p50_percent_rank FROM orders GROUP BY channel, CASE WHEN discount >= 0.34 THEN 'HIGH' ELSE 'LOW' END, status HAVING discount_per_returned < 1000000 ORDER BY status ASC;
